use arrow_array::{Array, Int32Array, ListArray, types::Int32Type};
use arrow_buffer::TrackingMemoryPool;
fn main() {
    let array = Int32Array::from_iter_values(0..1000);
    let slice = array.slice(0, 1);
    let raw_slice = array.to_data().slice(0, 1);
    println!("arraydata_slice buffer_len={} slice_bytes={}", raw_slice.buffers()[0].len(), raw_slice.get_slice_memory_size().unwrap());
    drop(raw_slice);
    let data = slice.to_data();
    println!("primitive_slice len={} buffer_len={} slice_bytes={}", data.len(), data.buffers()[0].len(), data.get_slice_memory_size().unwrap());
    let lists = ListArray::from_iter_primitive::<Int32Type, _, _>(vec![Some(vec![Some(1)]), Some(vec![Some(2);1000])]);
    let one = lists.slice(0, 1);
    println!("list_slice len={} visible_values={} slice_bytes={}", one.len(), one.value(0).len(), one.to_data().get_slice_memory_size().unwrap());
    let first = TrackingMemoryPool::default();
    let second = TrackingMemoryPool::default();
    array.claim(&first);
    println!("initial_claim first={} second={}", first.allocated(), second.allocated());
    slice.claim(&second);
    println!("claim_same_allocation_other_pool first={} second={}", first.allocated(), second.allocated());
    drop(array);
    drop(data);
    println!("only_slice_alive first={} second={}", first.allocated(), second.allocated());
    drop(slice);
    println!("all_owners_dropped first={} second={}", first.allocated(), second.allocated());
    std::panic::set_hook(Box::new(|_| {}));
    let a = std::hint::black_box(i64::MIN);
    let b = std::hint::black_box(-1_i64);
    let old = std::panic::catch_unwind(|| b != 0 && a % b == 0);
    println!("p4_division_guard_panics={} checked_remainder={:?}", old.is_err(), a.checked_rem(b));
}

