import importlib.util, json, sys
import pyarrow as pa
spec = importlib.util.spec_from_file_location("pse_transfer_review_probe", "python/pse/_transfer.py")
module = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = module
spec.loader.exec_module(module)
def map_schema(value):
    return pa.schema([pa.field("m", pa.map_(pa.int32(), pa.field("value", pa.int64(), metadata={b"meaning": value})))])
def struct_schema(value):
    return pa.schema([pa.field("s", pa.struct([pa.field("v", pa.int64(), metadata={b"meaning": value})]))])
def observations(left, right):
    return [[list(item.path), item.state] for item in module.compare_schemas(left, right)]
a, b = map_schema(b"a"), map_schema(b"b")
print(json.dumps({
    "pyarrow_version": pa.__version__,
    "map_source_field_equals_metadata": a.field(0).equals(b.field(0), check_metadata=True),
    "map_type_child_count": a.field(0).type.num_fields,
    "current_map_transfer": observations(a, b),
    "struct_control": observations(struct_schema(b"a"), struct_schema(b"b")),
}))
